package com.bank.prime;

import java.util.*;
import java.util.logging.*;

public class PrimeDemo {
    private static final Logger log = Logger.getLogger("Prime");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        PrimeService service = new PrimeService();
        log.info(() -> "Primes up to 30: " + service.primesUpTo(30));
    }
}

// ─── Would be in service/PrimeService.java ───
class PrimeService {
    // predicate: is k prime? check divisors up to sqrt(k)
    boolean isPrime(int k) {
        if (k < 2) return false;
        return java.util.stream.IntStream.rangeClosed(2, (int) Math.sqrt(k))
            .noneMatch(d -> k % d == 0);   // no divisor found → prime
    }

    List<Integer> primesUpTo(int n) {
        return java.util.stream.IntStream.rangeClosed(2, n)
            .filter(this::isPrime)          // keep primes
            .boxed()
            .toList();
    }
}
